const LOGOS = {"biography":"data:image/svg+xml;base64,","cosmopolitan":"data:image/svg+xml;base64,","country-living":"data:image/svg+xml;base64,","delish":"data:image/svg+xml;base64,","good-housekeeping":"data:image/svg+xml;base64,","house-beautiful":"data:image/svg+xml;base64,","prevention":"data:image/svg+xml;base64,","redbook":"data:image/svg+xml;base64,","seventeen":"data:image/svg+xml;base64,","the-pioneer-woman":"data:image/svg+xml;base64,","womans-day":"data:image/svg+xml;base64,","autoweek":"data:image/svg+xml;base64,","car-and-driver":"data:image/svg+xml;base64,","road-and-track":"data:image/svg+xml;base64,","elle-decor":"data:image/svg+xml;base64,","elle":"data:image/svg+xml;base64,","esquire":"data:image/svg+xml;base64,","harpers-bazaar":"data:image/svg+xml;base64,","town-and-country":"data:image/svg+xml;base64,","veranda":"data:image/svg+xml;base64,","best-products":"data:image/svg+xml;base64,","bicycling":"data:image/svg+xml;base64,","mens-health":"data:image/svg+xml;base64,","oprah-daily":"data:image/svg+xml;base64,","popular-mechanics":"data:image/svg+xml;base64,","runners-world":"data:image/svg+xml;base64,","womens-health":"data:image/svg+xml;base64,"};     // { slug: data URI }
